pragma solidity ^0.8.20;

import {SecureOraclePool} from "../src/SecureOraclePool.sol";
import {ITWAPOracle} from "../src/SecureOraclePool.sol";

contract ExploitModule {
    SecureOraclePool public targetContract;
    ITWAPOracle public oracle;

    constructor(address _target) payable {
        targetContract = SecureOraclePool(payable(_target));
        oracle = targetContract.twapOracle();
    }

    function runExploit() external payable {
        // Deposit collateral into the pool
        targetContract.depositCollateral{value: 1 ether}();

        // Borrow funds using TWAP oracle
        targetContract.borrow(1 ether);

        // Transfer back the borrowed funds to the pool
        payable(address(targetContract)).transfer(1 ether);
    }

    receive() external payable {
        // Reentrancy / callback handling if applicable
    }
}
